 const addL=(arr,items)=>{const seen=new Set(arr.map(x=>nk(Array.isArray(x)?x[1]:x)));for(const it of items){const v=Array.isArray(it)?it[1]:it,k=nk(v);if(v&&k&&!seen.has(k)){seen.add(k);arr.push(it)}}};
 const lv={e:'easy',m:'medium',h:'hard'};
 for(const k in XC2){if(!CATS[k])continue;
  const allH=[...CATS[k].word.easy,...CATS[k].word.medium,...CATS[k].word.hard],allE=EN[k]?[...EN[k].word.easy,...EN[k].word.medium,...EN[k].word.hard]:[];
  const sH=new Set(allH.map(nk)),sE=new Set(allE.map(nk));
  for(const l in XC2[k])for(const [h,n] of XP(XC2[k][l])){const kh=nk(h);if(h&&!sH.has(kh)){sH.add(kh);CATS[k].word[lv[l]].push(h)}
   const ke=nk(n||'');if(n&&EN[k]&&!sE.has(ke)){sE.add(ke);EN[k].word[lv[l]].push(n)}}}
 for(const k in XN2)if(NC[k]&&NC[k].items)addL(NC[k].items,XP(XN2[k]).map(([h,n])=>['',h,n||h]));
